const ZONE = 'Africa/Abidjan';
const now = $now.setZone(ZONE);
const dateFr = now.setLocale('fr').toFormat('cccc dd MMMM yyyy');

// Les deux canaux ne parlent pas la meme langue de balisage.
//
// Telegram, quand on lui demande d'analyser, lit du HTML : une esperluette
// dans un nom de produit fait echouer l'envoi entier. On echappe donc.
const ech = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .trim();

// WhatsApp, lui, met en gras entre asterisques et en italique entre tirets
// bas, sans jamais echouer. Le risque n'y est que cosmetique : un nom qui
// contient ces caracteres deformerait la mise en forme. On les retire.
const net = (v) => String(v ?? '').replace(/[*_~`]/g, '').trim();

const fcfa = (n) => Number(n || 0).toLocaleString('fr-FR');

const rep = $('Activite du jour').first().json || {};
const boutiques = rep.boutiques || [];
const plats = rep.plats || [];

// Aucune activite : pas de rapport plutot qu'un rapport vide.
if (!boutiques.length) return [];

const platsParBoutique = new Map();
for (const p of plats) {
  if (!platsParBoutique.has(p.slug)) platsParBoutique.set(p.slug, []);
  platsParBoutique.get(p.slug).push(p);
}

// Ou joindre chaque marchand. Un rapport ne doit jamais partir vers un chat
// qui n'est pas celui de la boutique dont il parle.
const annuaire = {};
for (const m of ($('Lire le registre').first().json.marchands) || []) {
  annuaire[String(m.id || '').trim()] = m;
}

const sorties = [];

for (const b of boutiques) {
  const slug = String(b.slug || '').trim();
  const m = annuaire[slug] || {};

  const top = (platsParBoutique.get(b.slug) || [])
    .map((p) => ({ brut: String(p.produit ?? ''), q: p.quantite }))
    .filter((p) => p.brut.trim())
    .slice(0, 3);

  const satisfaction = b.avis > 0
    ? `${String(b.note_moyenne).replace('.', ',')}/5 (${b.avis} avis)`
    : null;

  // --- Variante Telegram : HTML, tout le variable echappe.
  let tg = `📊 <b>RAPPORT QUOTIDIEN</b>\n🗓️ ${ech(dateFr)}\n`;
  tg += `\n🏪 <b>${ech(b.boutique_nom)}</b>\n\n`;
  tg += `▸ Commandes : <b>${ech(b.commandes)}</b>\n`;
  tg += `▸ Livrees : <b>${ech(b.livrees)}</b> ✅ | Annulees : <b>${ech(b.annulees)}</b> ❌\n`;
  tg += `▸ Chiffre d'affaires : <b>${ech(fcfa(b.ca))} FCFA</b>\n`;
  tg += `▸ Panier moyen : <b>${ech(fcfa(b.panier_moyen))} FCFA</b>\n`;
  if (top.length) {
    tg += `\n🍽️ <b>Top produits</b>\n`;
    for (const p of top) tg += `▸ ${ech(p.brut)} : <b>${ech(p.q)}</b>\n`;
  }
  tg += `\n⭐ Satisfaction : `;
  tg += satisfaction ? `<b>${ech(satisfaction)}</b>\n` : `aucun avis aujourd'hui\n`;
  tg += `\n━━━━━━━━\nGenere automatiquement par DjiguiFlow 🤖`;

  // --- Variante WhatsApp : asterisques natifs, rien a echapper.
  let wa = `📊 *RAPPORT QUOTIDIEN*\n🗓️ ${dateFr}\n`;
  wa += `\n🏪 *${net(b.boutique_nom)}*\n\n`;
  wa += `▸ Commandes : *${b.commandes}*\n`;
  wa += `▸ Livrees : *${b.livrees}* ✅ | Annulees : *${b.annulees}* ❌\n`;
  wa += `▸ Chiffre d'affaires : *${fcfa(b.ca)} FCFA*\n`;
  wa += `▸ Panier moyen : *${fcfa(b.panier_moyen)} FCFA*\n`;
  if (top.length) {
    wa += `\n🍽️ *Top produits*\n`;
    for (const p of top) wa += `▸ ${net(p.brut)} : *${p.q}*\n`;
  }
  wa += `\n⭐ Satisfaction : `;
  wa += satisfaction ? `*${satisfaction}*\n` : `aucun avis aujourd'hui\n`;
  wa += `\n━━━━━━━━\nGenere automatiquement par DjiguiFlow 🤖`;

  sorties.push({ json: {
    slug,
    message_telegram: tg,
    message_whatsapp: wa,
    telegram: String(m.telegramMarchand || '').trim(),
    whatsapp: String(m.whatsapp || '').trim(),
  } });
}

return sorties;

// Le plafond est attache a chaque boutique par l'application, dans le rapport
// d'activite. On le lit ici plutot que de le recalculer.
const parSlug = new Map();
for (const b of ($('Activite du jour').first().json.boutiques) || []) {
  if (b && b.slug) parSlug.set(String(b.slug).trim(), b);
}

return $input.all().map((item) => {
  const b = parSlug.get(String(item.json.slug || '').trim());

  // Pas de plafond attache : compte interne, ou lecture manquee cote
  // application. On se tait plutot que d'annoncer un chiffre invente.
  if (!b || typeof b.quota_inclus !== 'number') return item;

  // En deca de quatre-vingts pour cent, la ligne n'apprend rien au marchand
  // et allonge son rapport pour rien.
  const niveau = String(b.quota_niveau || '');
  if (niveau !== 'proche' && niveau !== 'critique' && niveau !== 'depasse') return item;

  const utilise = Number(b.quota_utilise) || 0;
  const inclus = Number(b.quota_inclus) || 0;
  const reste = Math.max(0, Number(b.quota_restant) || 0);

  // Pas de balise ici : la variante Telegram part en HTML, et une balise mal
  // fermee ferait echouer l'envoi entier du rapport.
  const ligne = niveau === 'depasse'
    ? `\n\n⛔ Plafond atteint : ${utilise}/${inclus} commandes ce mois. Les nouvelles commandes ne sont plus enregistrees.\nhttps://www.djiguiflow.com/dashboard/paiements`
    : `\n\n⚠️ Plafond bientot atteint : ${utilise}/${inclus} commandes ce mois, il vous en reste ${reste}.\nhttps://www.djiguiflow.com/dashboard/paiements`;

  return { json: {
    ...item.json,
    message_telegram: String(item.json.message_telegram || '') + ligne,
    message_whatsapp: String(item.json.message_whatsapp || '') + ligne,
  } };
});

